CREATE TABLE IF NOT EXISTS tenants(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL);
CREATE TABLE IF NOT EXISTS admins(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants, username text UNIQUE NOT NULL, password_hash text NOT NULL);
CREATE TABLE IF NOT EXISTS admin_sessions(token_hash text PRIMARY KEY, admin_id uuid NOT NULL REFERENCES admins, expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS login_codes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants, label text NOT NULL, code_hash text UNIQUE NOT NULL, suffix text NOT NULL, enabled boolean NOT NULL DEFAULT true, expires_at timestamptz NOT NULL, max_devices int NOT NULL CHECK(max_devices BETWEEN 1 AND 100), max_accounts int NOT NULL CHECK(max_accounts BETWEEN 1 AND 500), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS devices(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants, code_id uuid NOT NULL REFERENCES login_codes, identity_hash text NOT NULL, name text NOT NULL, active boolean NOT NULL DEFAULT true, last_seen timestamptz NOT NULL DEFAULT now(), UNIQUE(code_id, identity_hash));
CREATE TABLE IF NOT EXISTS client_sessions(token_hash text PRIMARY KEY, device_id uuid NOT NULL REFERENCES devices, expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS proxies(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants, label text NOT NULL, protocol text NOT NULL, host text NOT NULL, port int NOT NULL, username text NOT NULL, password_cipher text NOT NULL, group_name text NOT NULL DEFAULT '默认分组', enabled boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS platform_accounts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants, code_id uuid NOT NULL REFERENCES login_codes, proxy_id uuid NOT NULL REFERENCES proxies, device_id uuid REFERENCES devices, platform text NOT NULL DEFAULT 'whatsapp', label text NOT NULL, observed_status text NOT NULL DEFAULT 'not_opened', observed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_logs(id bigserial PRIMARY KEY, tenant_id uuid REFERENCES tenants, actor text NOT NULL, action text NOT NULL, success boolean NOT NULL, ip text NOT NULL, device text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS devices_code_idx ON devices(code_id);
CREATE INDEX IF NOT EXISTS accounts_tenant_idx ON platform_accounts(tenant_id);
CREATE INDEX IF NOT EXISTS logs_tenant_idx ON audit_logs(tenant_id,created_at DESC);
